<?php declare(strict_types=1);namespace StudPulse\Integrations;use StudPulse\Config;use StudPulse\Database\DB;use StudPulse\Security\{Auth,Crypto};use StudPulse\Domain\Backup;use StudPulse\Http\{ApiError,Request};final class GoogleDrive{public const APPDATA_SCOPE='https://www.googleapis.com/auth/drive.appdata';public const FILE_SCOPE='https://www.googleapis.com/auth/drive.file';public const SYNC_SCOPE='https://www.googleapis.com/auth/drive';public function configured():bool{return Config::get('GOOGLE_CLIENT_ID')!==''&&Config::get('GOOGLE_CLIENT_SECRET')!==''&&str_starts_with(Config::get('GOOGLE_REDIRECT_URI'),'https://');}public function status(Auth$a):array{$a->browserOnly();$c=DB::one('SELECT scopes,expiry,revoked_at,google_subject IS NOT NULL AS account_confirmed FROM google_connections WHERE user_id=?',[$a->user['id']]);$connected=$c&&$c['revoked_at']===null;$fileGranted=$connected&&$c['account_confirmed']&&array_intersect([self::FILE_SCOPE,self::SYNC_SCOPE],json_decode($c['scopes'],true)?:[]);return['configured'=>$this->configured(),'connected'=>$connected,'fileGranted'=>$fileGranted,'connection'=>$c,'scope'=>'drive.appdata drive.file','library'=>DriveLibrary::status($a),'lastBackup'=>DB::one('SELECT id,status,finished_at,error_redacted FROM google_backup_jobs WHERE user_id=? ORDER BY started_at DESC LIMIT 1',[$a->user['id']]),'calendar'=>'not_configured','binaryBackup'=>'group_library'];}public function start(Auth$a,?Request$request=null):array{$a->browserOnly();$scope=self::APPDATA_SCOPE.' '.self::FILE_SCOPE;$syncConsent=($request?->body['syncAccess']??false)===true;if($syncConsent){$root=DriveSync::groupRoot(DriveSync::manager($a));if($root&&$root['user_id']!==$a->user['id']){throw new ApiError(403,'DRIVE_SYNC_OWNER','Доступ к папке подтверждает владелец подключения');}$scope.=' '.self::SYNC_SCOPE;}if(!$this->configured()){throw new ApiError(503,'GOOGLE_NOT_CONFIGURED','Нужны собственные Google OAuth credentials и HTTPS callback');}$state=Crypto::token();$ve