ланировщик не смог прочитать сохранённое подключение Google. Проверьте, что сайт и PHP CLI используют одну конфигурацию ключа шифрования, или подтвердите доступ Google заново.');}if(!is_array($t)||!is_string($t['access_token']??null)||$t['access_token']===''){throw new ApiError(409,'GOOGLE_REAUTH_REQUIRED','В сохранённом подключении отсутствует токен доступа. Подключите Google Drive заново.');}if(strtotime($c['expiry'].' UTC')<time()+60){if(!isset($t['refresh_token'])){throw new ApiError(409,'GOOGLE_REAUTH_REQUIRED','Повторите подключение Google');}try{$new=HttpClient::request('POST','https://oauth2.googleapis.com/token',['Content-Type: application/x-www-form-urlencoded'],http_build_query(['client_id'=>Config::get('GOOGLE_CLIENT_ID'),'client_secret'=>Config::get('GOOGLE_CLIENT_SECRET'),'refresh_token'=>$t['refresh_token'],'grant_type'=>'refresh_token']))['json'];}catch(ApiError$e){if($e->errorCode==='GOOGLE_INVALID_GRANT'||$e->errorCode==='GOOGLE_REAUTH_REQUIRED'){DB::run("UPDATE google_connections SET revoked_at=UTC_TIMESTAMP(6),tokens_encrypted='' WHERE user_id=? AND tokens_encrypted=?",[$userId,$c['tokens_encrypted']]);}throw$e;}if(!is_string($new['access_token']??null)||$new['access_token']===''){throw new ApiError(502,'GOOGLE_RESPONSE','Некорректный ответ Google');}$t=array_replace($t,$new);if(!DB::run('UPDATE google_connections SET tokens_encrypted=?,expiry=? WHERE user_id=? AND tokens_encrypted=? AND revoked_at IS NULL',[Crypto::encrypt(json_encode($t,JSON_THROW_ON_ERROR)),gmdate('Y-m-d H:i:s',time()+(int)($new['expires_in']??3600)),$userId,$c['tokens_encrypted']])->rowCount()){throw new ApiError(409,'GOOGLE_CONNECTION_CHANGED','Подключение Google изменилось');}}return'Authorization: Bearer '.$t['access_token'];}public function backup(Auth$a):array{$a->browserOnly();return$this->backupFor($a,DB::id());}public function backupFor(Auth$a,string$id,?string$account=null):array{$auth=$this->bearerFor($a->user['id'],$account);DB::run("INSERT IGNORE INTO google_backup_jobs(id,user_id,status,started_at) VALUES(?,?,'running',UTC_TIMESTAMP(6))",[$id,$a->user['id']]);if($account!==null){$existing=HttpClient::request('GET','https://www.googleapis.com/drive/v3/files?'.http_build_query(['spaces'=>'appDataFolder','fields'=>'files(id)','q'=>"name='studpulse-$id.json.enc' and trashed=false",],'','&',PHP_QUERY_RFC3986),[$auth])['json']['files'][0]['id']??null;if($existing){DB::run("UPDATE google_backup_jobs SET status='completed',finished_at=UTC_TIMESTAMP(6),remote_file_id=? WHERE id=?",[$existing,$id]);return['id'=>$id,'remoteFileId'=>$existing,'includes'=>'settings_and_personal_text_only'];}}try{$content=Crypto::encrypt(json_encode(Backup::manifest($a),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$boundary='sp'.bin2hex(random_bytes(16));$meta=json_encode(['name'=>'studpulse-'.$id.'.json.enc','parents'=>['appDataFolder']],JSON_THROW_ON_ERROR);$body="--$boundary\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n$meta\r\n--$boundary\r\nContent-Type: application/octet-stream\r\n\r\n$content\r\n--$boundary--\r\n";$f=HttpClient::request('POST','https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart',[$auth,'Content-Type: multipart/related; boundary='.$boundary],$body)['json'];if(!isset($f['id'])){throw new ApiError(502,'GOOGLE_RESPONSE','Файл копии не подтверждён');}DB::run("UPDATE google_backup_jobs SET status='completed',finished_at=UTC_TIMESTAMP(6),remote_file_id=? WHERE id=?",[$f['id'],$id]);return['id'=>$id,'remoteFileId'=>$f['id'],'includes'=>'settings_and_personal_text_only'];}catch(\Throwable$e){DB::run("UPDATE google_backup_jobs SET status='failed',finished_at=UTC_TIMESTAMP(6),error_redacted='Google backup failed' WHERE id=?",[$id]);throw$e;}}public function files(Auth$a):array{$a->browserOnly();return HttpClient::request('GET','https://www.googleapis.com/drive/v3/files?spaces=appDataFolder&pageSize=50&fields=files(id,name,modifiedTime)&orderBy=modifiedTime%20desc',[$this->bearer($a)])['json']??[];}public function preview(Auth$a,Request$r):array{$a->browserOnly(true);$id=$r->body['fileId']??'';if(!is_string($id)||!preg_match('/^[A-Za-z0-9_-]{1,150}$/',$id)){throw new ApiError(422,'VALIDATION','Некорректный файл');}$raw=HttpClient::request('GET','https://www.googleapis.com/drive/v3/files/'.rawurlencode($id).'?alt=media',[$this->bearer($a)])['raw'];$manifest=json_decode(Crypto::decrypt($raw),true,32,JSON_THROW_ON_ERROR);$plan=Backup::preview($a,$manifest);return['plan'=>$plan,'manifest'=>$manifest,'confirmation'=>Crypto::hash($a->user['id'].json_encode($manifest,JSON_THROW_ON_ERROR))];}public function restore(Auth$a,Request$r):array{$a->browserOnly(true);$m=$r->body['manifest']??[];if(($r->body['confirmed']??false)!==true||!hash_equals(Crypto::hash($a->user['id'].json_encode($m,JSON_THROW_ON_ERROR)),(string)($r->body['confirmation']??''))){throw new ApiError(422,'RESTORE_CONFIRM','Нужны предпросмотр и явное подтверждение');}return Backup::restore($a,$m);}public function disconnect(Auth$a):array{$a->browserOnly();$user=$a->user['id'];$c=DB::transaction(static function()use($user):?array{$connection=DB::one('SELECT tokens_encrypted FROM google_connections WHERE user_id=? AND revoked_at IS NULL FOR UPDATE',[$user]);DB::run('DELETE FROM google_connections WHERE user_id=?',[$user]);DB::run("DELETE FROM oauth_states WHERE user_id=? AND provider IN ('google','google_sync')",[$user]);return$connection;});$revoked=false;if($c){try{$t=json_decode(Crypto::decrypt($c['tokens_encrypted']),true);HttpClient::request('POST','https://oauth2.googleapis.com/revoke',['Content-Type: application/x-www-form-urlencoded'],http_build_query(['token'=>$t['refresh_token']??$t['access_token']]));$revoked=true;}catch(\Throwable){}}return['disconnected'=>true,'remoteRevocationConfirmed'=>$revoked,'remoteFilesDeleted'=>false];}}